fn hx(x:&str)->N{N::parse_bytes(x.trim_start_matches("0x").as_bytes(),16).unwrap()}
fn addp(f:&F,a:&P,b:&P)->P{let mut c=a.clone();c.resize(a.len().max(b.len()),n(0));for(i,x)in b.iter().enumerate(){c[i]=f.add(&c[i],x);}trim(c)}
fn div(f:&F,mut a:P,b:&P)->(P,P){assert!(!b.is_empty());if a.len()<b.len(){return(vec![],a);}let mut q=vec![n(0);a.len()-b.len()+1];let inv=f.inv(b.last().unwrap());while !a.is_empty()&&a.len()>=b.len(){let j=a.len()-b.len();let t=f.mul(a.last().unwrap(),&inv);q[j]=f.add(&q[j],&t);for(i,x)in b.iter().enumerate(){a[i+j]=f.sub(&a[i+j],&f.mul(&t,x));}a=trim(a);}(trim(q),a)}
struct Model{f:F,a:N,b:N,z:N,yt:N}
fn formula(m:&Model,h:&N,k:&N,r:&N,s:&N)->P{let f=&m.f;let(h2,k2,r2,s2,z2)=(f.mul(h,h),f.mul(k,k),f.mul(r,r),f.mul(s,s),f.mul(&m.z,&m.z));let z3=f.mul(&z2,&m.z);let z4=f.mul(&z2,&z2);let e1=f.add(&f.add(&h2,h),&m.z);let e2=f.add(&f.add(&f.add(&f.add(&r2,&f.mul(h,r)),k),&f.mul(&h2,&m.a)),&f.mul(&m.z,&e1));let e3=f.add(&f.add(&f.add(&f.mul(h,s),&f.mul(k,r)),&k2),&f.mul(&m.z,&e2));
 let e4=s2.clone()^f.mul(k,s)^f.mul(&m.z,&f.mul(k,r))^f.mul(&z2,&r2)^f.mul(&k2,&f.add(&m.a,&m.z))^f.mul(&z2,k)^f.mul(&h2,&f.mul(&m.yt,&m.yt))^f.mul(&f.mul(h,k),&m.yt)^z4.clone();
 let e5=f.mul(&m.z,&s2)^f.mul(&z3,&r2)^f.mul(&k2,&(m.yt.clone()^f.mul(&m.z,&m.a)^z2.clone()))^f.mul(&m.z,&f.mul(&h2,&f.mul(&m.yt,&m.yt)))^f.mul(&z4,&m.z);vec![e5,e4,e3,e2,e1,n(1)]}
fn literal(m:&Model,h:&N,k:&N,r:&N,s:&N)->P{let f=&m.f;let z2=f.mul(&m.z,&m.z);let t=f.mul(&z2,&m.z)^f.mul(r,&z2)^f.mul(s,&m.z)^f.mul(&(f.mul(h,&m.z)^k),&m.yt);let p=vec![t,s.clone(),r.clone(),n(1)];let q=trim(vec![k.clone(),h.clone()]);let curve=vec![m.b.clone(),n(0),m.a.clone(),n(1)];let pq=f.mulp(&p,&q);let mut xpq=vec![n(0)];xpq.extend(pq);let norm=addp(f,&addp(f,&f.mulp(&p,&p),&xpq),&f.mulp(&f.mulp(&q,&q),&curve));let(quot,rem)=div(f,norm,&vec![m.z.clone(),n(1)]);assert!(rem.is_empty());quot}
fn uv(f:&F,h:&P)->(N,N){(f.add(&h[2],&f.mul(&h[4],&h[3])),f.add(&h[0],&f.mul(&h[4],&h[1])))}
fn corrected_uv(m:&Model,h:&N,k:&N,r:&N,s:&N,hs:&P)->(N,N){let f=&m.f;let c=f.add(&f.mul(h,h),h);let u=f.mul(h,s)^f.mul(k,r)^f.mul(k,k)^f.mul(&c,&hs[3]);let z2=f.mul(&m.z,&m.z);let inner=f.mul(&m.z,s)^f.mul(&z2,r)^f.mul(k,&m.yt)^f.mul(&z2,&m.z)^f.mul(&f.mul(h,&m.z),&m.yt);(u,f.mul(&c,&hs[1])^f.mul(k,&inner))}
fn span(cols:&[N],width:usize)->Vec<N>{let mut b=vec![n(0);width];for col in cols{let mut x=col.clone();while !x.is_zero(){let i=x.bits()as usize-1;if b[i].is_zero(){b[i]=x;break;}x^=&b[i];}}b}
fn residual(mut x:N,b:&[N])->N{for i in (0..b.len()).rev(){if x.bit(i as u64)&&!b[i].is_zero(){x^=&b[i];}}x}
fn rank(cols:&[N],width:usize)->usize{span(cols,width).iter().filter(|x|!x.is_zero()).count()}
fn product_spans(f:&F,basis:&[N],width:usize)->Vec<Vec<N>>{let mut b=span(basis,width);let mut out=vec![b.clone()];for _ in 0..4{let cols=b.iter().filter(|x|!x.is_zero()).flat_map(|a|basis.iter().map(move|b|f.mul(a,b))).collect::<Vec<_>>();b=span(&cols,width);out.push(b.clone());}out}
fn packed(h:&P,spans:&[Vec<N>],width:usize)->N{let mut x=n(0);for j in 2..=5{x|=residual(h[5-j].clone(),&spans[j-1])<<((j-2)*width);}x}
struct Family{part:Option<N>,kernel:Vec<N>,rank:usize}
fn solve(cols:&[N],rhs:&N,width:usize)->Family{let mut piv:Vec<Option<(N,N)>>=vec![None;width];let mut ker=vec![];let mut rank=0;for(j,col)in cols.iter().enumerate(){let mut x=col.clone();let mut t=N::one()<<j;while !x.is_zero(){let i=x.bits()as usize-1;if let Some((b,k))=&piv[i]{x^=b;t^=k;}else{piv[i]=Some((x.clone(),t.clone()));rank+=1;break;}}if x.is_zero(){ker.push(t);}}let mut x=rhs.clone();let mut t=n(0);while !x.is_zero(){let i=x.bits()as usize-1;if let Some((b,k))=&piv[i]{x^=b;t^=k;}else{return Family{part:None,kernel:ker,rank};}}assert_eq!(rank+ker.len(),cols.len());Family{part:Some(t),kernel:ker,rank}}
fn rs(mask:&N,width:usize)->(N,N){let low=(N::one()<<width)-n(1);(mask&low,mask>>width)}
fn family(m:&Model,h:&N,k:&N,spans:&[Vec<N>],width:usize)->Family{let base=formula(m,h,k,&n(0),&n(0));assert!(residual(base[4].clone(),&spans[0]).is_zero(),"outer not admitted");let rhs=packed(&base,spans,width);let cols=(0..2*width).map(|j|{let(r,s)=rs(&(N::one()<<j),width);packed(&formula(m,h,k,&r,&s),spans,width)^&rhs}).collect::<Vec<_>>();solve(&cols,&rhs,4*width)}
fn validate_family(m:&Model,h:&N,k:&N,spans:&[Vec<N>],width:usize,fam:&Family){if let Some(p)=&fam.part{let(r,s)=rs(p,width);let base=formula(m,h,k,&r,&s);assert_eq!(base,literal(m,h,k,&r,&s));assert!(packed(&base,spans,width).is_zero());for mask in &fam.kernel{let(r,s)=rs(&(p^mask),width);let hpoly=formula(m,h,k,&r,&s);assert_eq!(hpoly,literal(m,h,k,&r,&s));assert!(packed(&hpoly,spans,width).is_zero());}}}
fn base_controls()->Value{let mut count=0;let mut rejected_old=0;for f in fields().into_iter().filter(|f|matches!(f.k,Kind::Binary(d,_)if d<=4)){let q=f.order().to_usize().unwrap();let m=Model{f,a:n(0),b:n(1),z:n(1),yt:n(0)};let lim=if q==4{q.pow(4)}else{1024};for i in 0..lim{let mut v=(i*1664525usize+1013904223usize)%q.pow(4);let mut a=vec![];for _ in 0..4{a.push(N::from(v%q));v/=q;}let h=formula(&m,&a[0],&a[1],&a[2],&a[3]);assert_eq!(h,literal(&m,&a[0],&a[1],&a[2],&a[3]));let u=uv(&m.f,&h);assert_eq!(u,corrected_uv(&m,&a[0],&a[1],&a[2],&a[3],&h));let missing=m.f.mul(&m.f.add(&m.f.mul(&a[0],&a[0]),&a[0]),&h[1]);if !missing.is_zero(){rejected_old+=1;}count+=1;}}
 let f=fields().into_iter().find(|f|f.name=="GF2^2").unwrap();let m=Model{f,a:n(0),b:n(1),z:n(1),yt:n(0)};let counter=formula(&m,&n(2),&n(0),&n(0),&n(0));assert_eq!(counter,vec![n(1),n(1),n(0),n(0),n(0),n(1)]);assert_eq!(uv(&m.f,&counter).1,n(1));let spans=product_spans(&m.f,&[n(1)],2);let mut family_controls=0;for hi in 0..4{for ki in 0..4{let h=n(hi);let k=n(ki);let hs=formula(&m,&h,&k,&n(0),&n(0));if !residual(hs[4].clone(),&spans[0]).is_zero(){continue;}let fam=family(&m,&h,&k,&spans,2);validate_family(&m,&h,&k,&spans,2,&fam);let mut generated=std::collections::BTreeSet::new();if let Some(p)=fam.part{for bits in 0..(1usize<<fam.kernel.len()){let mut z=p.clone();for(i,b)in fam.kernel.iter().enumerate(){if bits>>i&1!=0{z^=b;}}assert!(generated.insert(z));}}for mask in 0u32..16{let z=n(mask);let(r,s)=rs(&z,2);let hs=literal(&m,&h,&k,&r,&s);assert_eq!(generated.contains(&z),packed(&hs,&spans,2).is_zero());family_controls+=1;}}}
 json!({"status":"passed","literal_norm_cases":count,"old_transfer_formula_counterexamples":rejected_old,"tiny_family_memberships":family_controls,"explicit_counterexample":"GF4,h=omega,k=r=s=0,z=1,yT=0 yields H=X^5+X+1,V=1"})}
fn p_at(m:&Model,h:&N,k:&N,r:&N,s:&N,x:&N)->N{let f=&m.f;let z2=f.mul(&m.z,&m.z);let t=f.mul(&z2,&m.z)^f.mul(r,&z2)^f.mul(s,&m.z)^f.mul(&(f.mul(h,&m.z)^k),&m.yt);vec![t,s.clone(),r.clone(),n(1)].iter().rev().fold(n(0),|v,c|f.mul(&v,x)^c)}
fn compose(base:&N,kernel:&[N],mask:&N)->N{let mut z=base.clone();for(i,k)in kernel.iter().enumerate(){if mask.bit(i as u64){z^=k;}}z}
fn domain_betas(f:&F,basis:&[N])->Vec<N>{let mut v=basis.to_vec();let mut out=vec![];for i in 0..v.len(){let b=v[i].clone();assert!(!b.is_zero());for x in v.iter_mut().skip(i+1){*x=f.mul(x,x)^f.mul(&b,x);}out.push(b);}out}
fn all_support(f:&F,h:&P,beta:&[N])->bool{let mut r=vec![n(0),n(1)];for b in beta{let sq=f.rem(f.mulp(&r,&r),h,false);let scale=r.iter().map(|x|f.mul(b,x)).collect::<Vec<_>>();r=addp(f,&sq,&scale);}for _ in 0..3{r=f.rem(f.mulp(&r,&r),h,false);}r.is_empty()}
pub fn controls()->Value{let mut v=base_controls();let f=fields().into_iter().find(|f|f.name=="GF2^2").unwrap();let m=Model{f,a:n(0),b:n(1),z:n(1),yt:n(0)};let mut c=0;for hi in 1..4{for ki in 0..4{let h=n(hi);let k=n(ki);let x=m.f.mul(&k,&m.f.inv(&h));if x==m.z{continue;}let square=m.f.product(&[x.clone(),x.clone()]);for ri in 0..4{for si in 0..4{let r=n(ri);let s=n(si);let hs=literal(&m,&h,&k,&r,&s);let expected=p_at(&m,&h,&k,&r,&s,&x).is_zero();let(_,rem)=div(&m.f,hs,&square);assert_eq!(rem.is_empty(),expected);c+=1;}}}}v["repeated_pair_divisibility_controls"]=json!(c);v}
pub fn run(id:&str,fixture:&str,profiles:&str)->Value{let input:Value=serde_json::from_slice(&std::fs::read(fixture).unwrap()).unwrap();let prof:Value=serde_json::from_slice(&std::fs::read(profiles).unwrap()).unwrap();let width=input["extension_field"]["degree"].as_u64().unwrap()as usize;assert_eq!(width,83);let modulus=hx(input["extension_field"]["modulus_hex"].as_str().unwrap());let f=F{name:"GF2^83".into(),k:Kind::Binary(width,modulus)};field_controls(&[f.clone()]);let z=hx(input["target"]["x_hex"].as_str().unwrap());let yt=hx(input["target"]["y_hex"].as_str().unwrap())^&z;let m=Model{f,a:hx(input["curve"]["a_hex"].as_str().unwrap()),b:hx(input["curve"]["b_hex"].as_str().unwrap()),z,yt};let f=&m.f;assert!(hx(input["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());let basis=input["source_basis_hex"].as_array().unwrap().iter().map(|x|hx(x.as_str().unwrap())).collect::<Vec<_>>();assert_eq!(basis.len(),18);let spans=product_spans(f,&basis,width);assert!(!residual(m.z.clone(),&spans[0]).is_zero(),"pole is in source domain; complementary pole branch required");let beta=domain_betas(f,&basis);let mut rows=vec![];let mut all_complete=true;
for p in prof["profiles"].as_array().unwrap(){let h=hx(p["d1_hex"].as_str().unwrap());let k=hx(p["d0_hex"].as_str().unwrap());assert!(!h.is_zero());let x=f.mul(&k,&f.inv(&h));if !residual(x.clone(),&spans[0]).is_zero(){rows.push(json!({"h":h.to_str_radix(16),"k":k.to_str_radix(16),"branch_empty":"Q root outside source domain","pair_branch_complete":true,"support_candidate_count_exact":0}));continue;}assert_ne!(x,m.z);let fam=family(&m,&h,&k,&spans,width);assert_eq!(fam.rank,93);assert_eq!(fam.kernel.len(),73);let base=fam.part.as_ref().unwrap();let(r0,s0)=rs(base,width);let rhs=p_at(&m,&h,&k,&r0,&s0,&x);let cols=fam.kernel.iter().map(|b|{let(r,s)=rs(&(base^b),width);p_at(&m,&h,&k,&r,&s,&x)^&rhs}).collect::<Vec<_>>();let pair=solve(&cols,&rhs,width);let mut found=vec![];let mut tested=0usize;let mut complete=true;let square=f.product(&[x.clone(),x.clone()]);if let Some(part)=&pair.part{if pair.kernel.len()>12{complete=false;all_complete=false;}else{for bits in 0..(1usize<<pair.kernel.len()){let mask=compose(part,&pair.kernel,&N::from(bits));let original=compose(base,&fam.kernel,&mask);let(r,s)=rs(&original,width);assert!(p_at(&m,&h,&k,&r,&s,&x).is_zero());let hs=formula(&m,&h,&k,&r,&s);assert_eq!(hs,literal(&m,&h,&k,&r,&s));assert!(packed(&hs,&spans,width).is_zero());let(q,rem)=div(f,hs.clone(),&square);assert!(rem.is_empty());assert_eq!(q.len(),4);tested+=1;if all_support(f,&hs,&beta){found.push(json!({"r":r.to_str_radix(16),"s":s.to_str_radix(16),"H":hs.iter().map(|x|x.to_str_radix(16)).collect::<Vec<_>>()}));}}}}
let count=if complete{json!(found.len())}else{Value::Null};rows.push(json!({"h":h.to_str_radix(16),"k":k.to_str_radix(16),"repeated_x":x.to_str_radix(16),"original_relaxed_dimension":73,"added_pair_constraint_rank":pair.rank,"pair_family_dimension":pair.kernel.len(),"pair_consistent":pair.part.is_some(),"tested_parameters":tested,"support_candidate_count_exact":count,"support_candidates":found,"pair_branch_complete":complete}));}
json!({"schema":"scientific_result_v1","experiment_id":id,"status":if all_complete{"passed"}else{"inconclusive"},"summary":"Repeated Q-root branch intersected with actual relaxed families and all admitted support candidates checked.","evidence":{"rows":rows,"original_root_count_exact":null,"scope":"four fixed-h,k norm families, Q(x)=P(x)=0 repeated-pair branch only; no original multivariate tuple completion","release_gate_claim":false,"source_tuple_reconstruction_complete":false},"next_actions":["Retain all complementary repeated tangency, squarefree and exceptional pole branches; this is not a full family solve.","Use the reduced cubic branch with exact source permutations and original Semaev auxiliary-fiber reconstruction before all-roots claims.","Generalize the repeated-root reduction to a bounded native tangency branch and compare complete matching baselines only after full coverage."]})}

