fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|s|s=="controls"){println!("{}",engine::controls());return;}let t=std::time::Instant::now();let mut out=engine::run(a.get(1).expect("id"),a.get(2).expect("fixture"),a.get(3).expect("profiles"));let mut encoded=out.to_string();if t.elapsed().as_secs()>=70{out["status"]=serde_json::json!("inconclusive");if let Some(rows)=out["evidence"]["rows"].as_array_mut(){for r in rows{r["pair_branch_complete"]=serde_json::json!(false);r["support_candidate_count_exact"]=serde_json::Value::Null;}}encoded=out.to_string();}println!("{encoded}");}
